create extension if not exists pgcrypto;
create table technical_sheets(id uuid primary key default gen_random_uuid(),reference text unique not null,data jsonb not null default '{}'::jsonb,created_by_user_id uuid,created_by_email text,updated_by_user_id uuid,updated_by_email text,created_at timestamptz default now(),updated_at timestamptz default now());
create table technical_sheet_components(id uuid primary key default gen_random_uuid(),technical_sheet_id uuid references technical_sheets(id) on delete cascade,data jsonb not null default '{}'::jsonb,created_by_user_id uuid,created_by_email text,updated_by_user_id uuid,updated_by_email text);
create table technical_sheet_markings(id uuid primary key default gen_random_uuid(),technical_sheet_id uuid references technical_sheets(id) on delete cascade,component_id uuid references technical_sheet_components(id) on delete set null,data jsonb not null default '{}'::jsonb,created_by_user_id uuid,created_by_email text,updated_by_user_id uuid,updated_by_email text);
create table technical_sheet_documents(id uuid primary key default gen_random_uuid(),technical_sheet_id uuid references technical_sheets(id) on delete cascade,component_id uuid references technical_sheet_components(id) on delete set null,storage_path text not null,file_name text not null,mime_type text,file_size bigint,created_by_user_id uuid,created_by_email text,created_at timestamptz default now());
